initJs:
function(container, apiUrl, tables) {
  let currentProducts = [];
  let currentStore = null;
  let demandPredictions = {};
  let inventoryData = {};

  // 初期データの設定
  const storeTable = tables.find(t => t.tableName === '店舗マスタ') || tables[1];
  const productTable = tables.find(t => t.tableName === '商品マスタ') || tables[2];
  const predictionTable = tables.find(t => t.tableName === '需要予測結果') || tables[8];
  const orderTable = tables.find(t => t.tableName === '発注データ') || tables[9];

  // 店舗選択肢を設定
  const storeSelect = container.querySelector('#select-store');
  if (storeTable && storeTable.records) {
    storeTable.records.forEach(store => {
      if (store.有効フラグ) {
        const option = document.createElement('option');
        option.value = store.店舗ID || store.id;
        option.textContent = `${store.店舗コード || ''} - ${store.店舗名 || ''}`;
        storeSelect.appendChild(option);
      }
    });
  }

  // 商品テーブル再描画関数
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');
    const tableWrap = container.querySelector('#product-table-wrap');
    const noStoreMsg = container.querySelector('#no-store-message');
    const noResultsMsg = container.querySelector('#no-results-message');

    if (!currentStore) {
      tableWrap.classList.add('hidden');
      noStoreMsg.classList.remove('hidden');
      noResultsMsg.classList.add('hidden');
      return;
    }

    noStoreMsg.classList.add('hidden');

    if (!products || products.length === 0) {
      tableWrap.classList.add('hidden');
      noResultsMsg.classList.remove('hidden');
      return;
    }

    noResultsMsg.classList.add('hidden');
    tableWrap.classList.remove('hidden');

    tbody.innerHTML = products.map(product => {
      const productId = product.商品ID || product.id;
      const prediction = demandPredictions[productId] || {};
      const inventory = inventoryData[productId] || 0;

      return `
        <tr data-id="${productId}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名|| ''}</td>
          <td>${getCategoryName(product.商品カテゴリID)}</td>
          <td>${inventory}</td>
          <td>${prediction.予測数量 || 0}</td>
          <td>${prediction.推奨発注数量 || 0}</td>
          <td>
            <input type="number" class="input order-quantity" data-product-id="${productId}" 
                   value="${prediction.推奨発注数量 || 0}" min="0" style="width: 80px;" 
                   data-testid="order-quantity-${productId}">
            <button class="action-btn secondary adjust-btn" data-product-id="${productId}" data-action="increase">+</button>
            <button class="action-btn secondary adjust-btn" data-product-id="${productId}" data-action="decrease">-</button>
          </td>
          <td>
            <input type="text" class="input order-reason" data-product-id="${productId}" 
                   placeholder="発注理由" style="width: 120px;" data-testid="order-reason-${productId}">
          </td>
          <td>
            <button class="action-btn order-btn" data-product-id="${productId}" data-testid="order-button-${productId}">発注</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // カテゴリ名取得
  function getCategoryName(categoryId) {
    const categories = {
      'cat1': '食品',
      'cat2': '日用品', 
      'cat3': '衣料品',
      'cat4': '家電'
    };
    return categories[categoryId] || '未分類';
  }

  // 需要予測結果表示
  function renderPredictionResults(storeId) {
    const predictionArea = container.querySelector('#prediction-area');
    if (!storeId) {
      predictionArea.innerHTML = '店舗を選択すると需要予測結果が表示されます';
      return;
    }

    const storeName = getStoreName(storeId);
    const totalPrediction = Object.values(demandPredictions).reduce((sum, p) => sum + (p.予測数量 || 0), 0);
    const totalRecommended = Object.values(demandPredictions).reduce((sum, p) => sum + (p.推奨発注数量 || 0), 0);

    predictionArea.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px;">
        <div>
          <div style="color: var(--text-muted); font-size: 14px;">対象店舗</div>
          <div style="color: var(--text); font-weight: bold;">${storeName}</div>
        </div>
        <div>
          <div style="color: var(--text-muted); font-size: 14px;">総予測需要量</div>
          <div style="color: var(--text); font-weight: bold;">${totalPrediction}個</div>
        </div>
        <div>
          <div style="color: var(--text-muted); font-size: 14px;">総推奨発注量</div>
          <div style="color: var(--text); font-weight: bold;">${totalRecommended}個</div>
        </div>
        <div>
          <div style="color: var(--text-muted); font-size: 14px;">予測精度</div>
          <div style="color: var(--text); font-weight: bold;">85%</div>
        </div>
      </div>
    `;
  }

  // 店舗名取得
  function getStoreName(storeId) {
    const store = storeTable.records?.find(s => (s.店舗ID || s.id) === storeId);
    return store ? `${store.店舗コード || ''} - ${store.店舗名 || ''}` : '不明';
  }

  // 商品データ読み込み
  async function loadProducts(storeId) {
    if (!storeId) {
      currentProducts = [];
      renderProducts([]);
      return;
    }

    try {
      // 商品データ取得
      const products = await window.aivicApi.list(2) || productTable.records || [];

      // 需要予測データ取得
      const predictions = await window.aivicApi.list(8) || predictionTable.records || [];
      demandPredictions = {};
      predictions.forEach(p => {
        if ((p.店舗ID || p.storeId) === storeId) {
          demandPredictions[p.商品ID || p.productId] = p;
        }
      });

      // 在庫データをサンプル生成
      inventoryData = {};
      products.forEach(p => {
        inventoryData[p.商品ID || p.id] = Math.floor(Math.random() * 100) + 10;
      });

      currentProducts = products.filter(p => p.有効フラグ !== false);
      currentStore = storeId;

      renderProducts(currentProducts);
      renderPredictionResults(storeId);
    } catch (error) {
      console.error('商品データの読み込みに失敗:', error);
      currentProducts = [];
      renderProducts([]);
    }
  }

  // 検索・フィルタ処理
  function filterProducts() {
    if (!currentStore) {
      renderProducts([]);
      return;
    }

    let filtered = [...currentProducts];

    // カテゴリフィルタ
    const category = container.querySelector('#select-category').value;
    if (category) {
      const categoryMap = {
        '食品': 'cat1',
        '日用品': 'cat2', 
        '衣料品': 'cat3',
        '家電': 'cat4'
      };
      filtered = filtered.filter(p => p.商品カテゴリID === categoryMap[category]);
    }

    // 商品名検索
    const searchTerm = container.querySelector('#input-search').value.toLowerCase();
    if (searchTerm) {
      filtered = filtered.filter(p => 
        (p.商品名 || '').toLowerCase().includes(searchTerm) ||
        (p.商品コード || '').toLowerCase().includes(searchTerm)
      );
    }

    renderProducts(filtered);
  }

  // バリデーション
  function validateOrderQuantity(quantity) {
    if (quantity === '' || quantity === null || quantity === undefined) {
      return { valid: false, message: '発注量を入力してください' };
    }

    const num = parseFloat(quantity);
    if (isNaN(num)) {
      return { valid: false, message: '発注量は数値で入力してください' };
    }

    if (num < 0) {
      return { valid: false, message: '発注量は正の数値を入力してください' };
    }

    if (num === 0) {
      return { valid: false, message: '発注量は1以上を入力してください' };
    }

    return { valid: true };
  }

  // 日付バリデーション
  function validateDateRange() {
    const startDate = container.querySelector('#input-date-start').value;
    const endDate = container.querySelector('#input-date-end').value;

    if (startDate && endDate && startDate > endDate) {
      alert('終了日は開始日以降の日付を入力してください');
      return false;
    }
    return true;
  }

  // 発注処理
  async function processOrder(productId, quantity, reason) {
    const validation = validateOrderQuantity(quantity);
    if (!validation.valid) {
      alert(validation.message);
      return false;
    }

    const product = currentProducts.find(p => (p.商品ID || p.id) === productId);
    if (!product) {
      alert('商品情報が見つかりません');
      return false;
    }

    // 発注確認モーダル表示
    const modal = container.querySelector('#order-modal');
    const details = container.querySelector('#order-details');

    details.innerHTML = `
      <div><strong>商品:</strong> ${product.商品名}</div>
      <div><strong>商品コード:</strong> ${product.商品コード}</div>
      <div><strong>発注量:</strong> ${quantity}個</div>
      <div><strong>発注理由:</strong> ${reason || '通常発注'}</div>
      <div><strong>発注金額:</strong> ${(quantity * (product.単価 || 0)).toLocaleString()}円</div>
    `;

    modal.classList.remove('hidden');

    return new Promise((resolve) => {
      const confirmBtn = container.querySelector('#btn-confirm-order');
      const cancelBtn = container.querySelector('#btn-cancel-order');

      const handleConfirm = async () => {
        try {
          const orderData = {
            店舗ID: currentStore,
            商品ID: productId,
            発注日: new Date().toISOString(),
            納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
            発注数量: parseInt(quantity),
            発注単価: product.単価 || 0,
            発注金額: quantity * (product.単価 || 0),
            発注方法: reason ? 'AI推奨修正' : 'AI推奨採用',
            発注ステータス: '発注済',
            発注理由: reason || '通常発注',
            自動発注フラグ: false,
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString(),
            作成者ID: 'current-user',
            更新者ID: 'current-user'
          };

          const result = await window.aivicApi.save(9, orderData);
          if (result) {
            alert('発注が完了しました');
            modal.classList.add('hidden');
            resolve(true);
          } else {
            alert('発注処理に失敗しました');
            resolve(false);
          }
        } catch (error) {
          console.error('発注エラー:', error);
          alert('発注処理でエラーが発生しました');
          resolve(false);
        }

        confirmBtn.removeEventListener('click', handleConfirm);
        cancelBtn.removeEventListener('click', handleCancel);
      };

      const handleCancel = () => {
        modal.classList.add('hidden');
        resolve(false);
        confirmBtn.removeEventListener('click', handleConfirm);
        cancelBtn.removeEventListener('click', handleCancel);
      };

      confirmBtn.addEventListener('click', handleConfirm);
      cancelBtn.addEventListener('click', handleCancel);
    });
  }

  // CSVエクスポート
  async function exportCSV() {
    try {
      const orders = await window.aivicApi.list(9) || [];
      const headers = ['発注ID', '店舗名', '商品名', '発注日', '発注数量', '発注金額', '発注ステータス', '発注理由'];

      let csvContent = '\uFEFF' + headers.join(',') + '\n';

      orders.forEach(order => {
        const storeName = getStoreName(order.店舗ID);
        const product = currentProducts.find(p => (p.商品ID || p.id) === order.商品ID);
        const productName = product ? product.商品名 : '不明';

        const row = [
          order.発注ID || order.id || '',
          `"${storeName}"`,
          `"${productName}"`,
          order.発注日 || '',
          order.発注数量 || 0,
          order.発注金額 || 0,
          order.発注ステータス || '',
          `"${order.発注理由 || ''}"`
        ];
        csvContent += row.join(',') + '\n';
      });

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `発注データ_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      console.error('CSVエクスポートエラー:', error);
      alert('CSVエクスポートに失敗しました');
    }
  }

  // イベントリスナー設定

  // 店舗選択
  container.querySelector('#select-store').addEventListener('change', (e) => {
    loadProducts(e.target.value);
  });

  // カテゴリ選択
  container.querySelector('#select-category').addEventListener('change', filterProducts);

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', () => {
    if (!validateDateRange()) return;
    filterProducts();
  });

  // CSVエクスポートボタン
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 商品検索（リアルタイム）
  container.querySelector('#input-search').addEventListener('input', filterProducts);

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 発注量調整ボタン
    const adjustBtn = e.target.closest('.adjust-btn');
    if (adjustBtn) {
      const productId = adjustBtn.dataset.productId;
      const action = adjustBtn.dataset.action;
      const quantityInput = container.querySelector(`input[data-product-id="${productId}"]`);
      let currentValue = parseInt(quantityInput.value) || 0;

      if (action === 'increase') {
        quantityInput.value = currentValue + 1;
      } else if (action === 'decrease' && currentValue > 0) {
        quantityInput.value = currentValue - 1;
      }
      return;
    }

    // 発注ボタン
    const orderBtn = e.target.closest('.order-btn');
    if (orderBtn) {
      const productId = orderBtn.dataset.productId;
      const quantityInput = container.querySelector(`input.order-quantity[data-product-id="${productId}"]`);
      const reasonInput = container.querySelector(`input.order-reason[data-product-id="${productId}"]`);

      const quantity = quantityInput.value;
      const reason = reasonInput.value;

      await processOrder(productId, quantity, reason);
      return;
    }
  });

  // 初期表示
  renderProducts([]);
  renderPredictionResults(null);
}
